import org.junit.jupiter.api.Test;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class TimeDependentServiceTest {

    @Test
    public void testTokenExpirationWithFixedClock() {
        // Fix the clock to avoid temporal flakiness in CI environments
        Instant fixedInstant = Instant.parse("2023-10-01T12:00:00Z");
        Clock fixedClock = Clock.fixed(fixedInstant, ZoneId.of("UTC"));

        TokenService service = new TokenService(fixedClock);
        assertTrue(service.isTokenValid(fixedInstant.plusSeconds(30)));
    }
}
